/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cache` (
  `key` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `value` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `expiration` bigint NOT NULL,
  PRIMARY KEY (`key`),
  KEY `cache_expiration_index` (`expiration`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `cache` WRITE;
/*!40000 ALTER TABLE `cache` DISABLE KEYS */;
/*!40000 ALTER TABLE `cache` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `cache_locks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cache_locks` (
  `key` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `owner` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expiration` bigint NOT NULL,
  PRIMARY KEY (`key`),
  KEY `cache_locks_expiration_index` (`expiration`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `cache_locks` WRITE;
/*!40000 ALTER TABLE `cache_locks` DISABLE KEYS */;
/*!40000 ALTER TABLE `cache_locks` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `exercises`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `exercises` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `muscle_group` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `difficulty` enum('beginner','intermediate','advanced') COLLATE utf8mb4_unicode_ci NOT NULL,
  `equipment` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `instructions` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_muscles` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tips` text COLLATE utf8mb4_unicode_ci,
  `image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `video_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `default_sets` int NOT NULL DEFAULT '3',
  `default_reps` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '10-12',
  `default_rest_seconds` int NOT NULL DEFAULT '60',
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `exercises_slug_unique` (`slug`),
  KEY `exercises_muscle_group_index` (`muscle_group`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `exercises` WRITE;
/*!40000 ALTER TABLE `exercises` DISABLE KEYS */;
INSERT INTO `exercises` VALUES (1,'Bench Press','bench-press','chest','intermediate','Barbell, ghế phẳng','Bài tập compound kinh điển phát triển sức mạnh và kích thước cơ ngực, đồng thời tác động vai trước và tay sau.','Nằm ngửa trên ghế phẳng, mắt thẳng dưới thanh đòn, hai bàn chân đặt chắc trên sàn.\nNắm thanh đòn rộng hơn vai một chút, siết bả vai về sau và xuống dưới.\nNhấc thanh đòn khỏi giá, giữ thẳng tay phía trên ngực.\nHít vào, hạ thanh đòn có kiểm soát xuống giữa ngực.\nThở ra, đẩy mạnh thanh đòn lên về vị trí ban đầu.','Ngực giữa, Vai trước, Tay sau','Không nảy thanh đòn trên ngực. Giữ cổ tay thẳng, khuỷu tay khoảng 45–70° so với thân. Nên có người hỗ trợ khi tập nặng.','images/exercises/chest.svg',NULL,4,'8-10',90,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(2,'Incline Dumbbell Press','incline-dumbbell-press','chest','intermediate','Dumbbell, ghế dốc','Biến thể đẩy ngực trên ghế dốc 30–45°, tập trung vào phần ngực trên.','Chỉnh ghế dốc 30–45°, ngồi tựa lưng, mỗi tay cầm một quả tạ đơn.\nĐưa tạ lên ngang vai, lòng bàn tay hướng về phía trước.\nĐẩy tạ thẳng lên trên cho đến khi gần duỗi thẳng tay.\nHạ tạ chậm về ngang ngực trên, cảm nhận cơ ngực giãn.','Ngực trên, Vai trước, Tay sau','Không để hai quả tạ va vào nhau ở đỉnh. Không chỉnh ghế quá dốc vì sẽ chuyển trọng tâm sang vai.','images/exercises/chest.svg',NULL,3,'10-12',60,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(3,'Push Up','push-up','chest','beginner','Không cần dụng cụ','Bài tập với trọng lượng cơ thể, dễ thực hiện ở mọi nơi, giúp tăng sức bền ngực và core.','Chống hai tay xuống sàn rộng hơn vai, thân người thẳng từ đầu đến gót.\nSiết cơ bụng và mông để giữ thân ổn định.\nHạ người xuống đến khi ngực gần chạm sàn.\nĐẩy người lên về vị trí ban đầu.','Ngực, Tay sau, Vai trước, Core','Không võng lưng hoặc chổng mông. Người mới có thể chống gối để giảm độ khó.','images/exercises/chest.svg',NULL,3,'12-15',60,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(4,'Chest Fly','chest-fly','chest','beginner','Dumbbell hoặc máy Pec Deck','Bài tập cô lập giúp kéo giãn và siết cơ ngực, bổ trợ cho các bài đẩy.','Nằm trên ghế phẳng, hai tay cầm tạ đơn đưa thẳng lên trên ngực.\nHơi khuỵu khuỷu tay, mở rộng hai tay sang hai bên theo hình vòng cung.\nHạ đến khi cảm thấy ngực căng giãn.\nKhép tay lại theo đường vòng cung, siết ngực ở đỉnh.','Ngực giữa, Vai trước','Dùng mức tạ vừa phải, giữ góc khuỷu tay cố định trong suốt chuyển động.','images/exercises/chest.svg',NULL,3,'12-15',60,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(5,'Pull Up','pull-up','back','advanced','Xà đơn','Bài kéo xà phát triển cơ lưng xô, tạo độ rộng cho lưng và tăng sức mạnh thân trên.','Nắm xà rộng hơn vai, lòng bàn tay hướng ra ngoài.\nTreo người thẳng tay, siết core.\nKéo người lên bằng cách hạ khuỷu tay xuống, đưa cằm vượt xà.\nHạ người chậm về vị trí treo ban đầu.','Lưng xô, Cơ tròn lớn, Tay trước','Không đung đưa người lấy đà. Có thể dùng dây kháng lực hoặc máy hỗ trợ khi mới tập.','images/exercises/back.svg',NULL,4,'6-8',90,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(6,'Lat Pulldown','lat-pulldown','back','beginner','Máy kéo cáp','Bài kéo cáp từ trên xuống, thay thế Pull Up cho người mới, tập trung lưng xô.','Ngồi vào máy, chỉnh đệm giữ đùi vừa vặn.\nNắm thanh kéo rộng hơn vai.\nƯỡn ngực nhẹ, kéo thanh xuống ngang ngực trên.\nSiết lưng 1 giây rồi trả thanh lên chậm.','Lưng xô, Cơ trám, Tay trước','Không ngả người ra sau quá nhiều, không kéo thanh ra sau gáy.','images/exercises/back.svg',NULL,3,'10-12',60,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(7,'Barbell Row','barbell-row','back','intermediate','Barbell','Bài chèo tạ đòn giúp tăng độ dày lưng giữa và sức mạnh kéo.','Đứng rộng bằng hông, cầm thanh đòn rộng bằng vai.\nGập hông, đẩy mông ra sau, thân trên nghiêng khoảng 45°, lưng thẳng.\nKéo thanh đòn về phía bụng dưới, khép bả vai.\nHạ thanh đòn có kiểm soát.','Lưng giữa, Lưng xô, Cầu vai sau','Giữ lưng trung tính, không giật người. Bắt đầu với mức tạ nhẹ để học kỹ thuật.','images/exercises/back.svg',NULL,4,'8-10',90,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(8,'Deadlift','deadlift','back','advanced','Barbell','Bài compound toàn thân, phát triển sức mạnh chuỗi cơ sau: lưng dưới, mông, đùi sau.','Đứng hai chân rộng bằng hông, thanh đòn sát ống quyển.\nGập hông và gối, nắm thanh đòn ngay ngoài hai chân.\nƯỡn ngực, giữ lưng thẳng, siết lưng xô.\nĐẩy chân xuống sàn, duỗi hông và gối để đứng thẳng.\nHạ thanh đòn theo đường thẳng sát chân về sàn.','Lưng dưới, Mông, Đùi sau, Cầu vai','Tuyệt đối không cong lưng. Khởi động kỹ và tăng tạ từ từ.','images/exercises/back.svg',NULL,3,'5',120,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(9,'Shoulder Press','shoulder-press','shoulders','intermediate','Dumbbell hoặc Barbell','Bài đẩy vai qua đầu phát triển toàn bộ cơ vai, đặc biệt vai trước và vai giữa.','Ngồi hoặc đứng thẳng, cầm tạ ngang vai, lòng bàn tay hướng trước.\nSiết core, đẩy tạ thẳng lên trên đầu.\nDuỗi gần thẳng tay ở đỉnh.\nHạ tạ về ngang vai có kiểm soát.','Vai trước, Vai giữa, Tay sau','Không ưỡn lưng dưới quá mức khi đẩy. Giữ cổ tay thẳng.','images/exercises/shoulders.svg',NULL,3,'10-12',60,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(10,'Lateral Raise','lateral-raise','shoulders','beginner','Dumbbell','Bài cô lập vai giữa, giúp vai rộng và tròn hơn.','Đứng thẳng, hai tay cầm tạ đơn ở hai bên hông.\nHơi khuỵu khuỷu, nâng tạ sang hai bên đến ngang vai.\nDừng 1 giây ở đỉnh.\nHạ tạ chậm về vị trí ban đầu.','Vai giữa','Dùng tạ nhẹ, không nhún vai hay lắc người lấy đà.','images/exercises/shoulders.svg',NULL,3,'12-15',45,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(11,'Front Raise','front-raise','shoulders','beginner','Dumbbell hoặc đĩa tạ','Bài cô lập vai trước, bổ trợ cho các bài đẩy.','Đứng thẳng, cầm tạ trước đùi.\nNâng tạ thẳng phía trước đến ngang tầm mắt.\nHạ tạ chậm về vị trí ban đầu.','Vai trước','Không ngả người ra sau. Có thể tập luân phiên từng tay.','images/exercises/shoulders.svg',NULL,3,'12',45,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(12,'Squat','squat','legs','intermediate','Barbell, khung squat','Vua của các bài tập chân, phát triển đùi trước, mông và sức mạnh toàn thân.','Đặt thanh đòn trên cầu vai, hai chân rộng bằng vai, mũi chân hơi mở.\nHít sâu, siết core.\nĐẩy hông ra sau và khuỵu gối, hạ người đến khi đùi song song sàn.\nĐẩy gót chân xuống sàn để đứng lên.','Đùi trước, Mông, Đùi sau, Core','Gối đi cùng hướng mũi chân, không để gối chụm vào trong. Giữ lưng thẳng.','images/exercises/legs.svg',NULL,4,'8-10',120,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(13,'Leg Press','leg-press','legs','beginner','Máy đạp đùi','Bài đạp đùi trên máy, an toàn cho người mới mà vẫn tải được mức tạ lớn.','Ngồi vào máy, lưng tựa sát đệm, đặt chân rộng bằng vai lên bàn đạp.\nMở khóa an toàn, hạ bàn đạp đến khi gối gập khoảng 90°.\nĐạp mạnh bàn đạp lên, không khóa gối ở đỉnh.','Đùi trước, Mông','Không để lưng dưới nhấc khỏi đệm khi hạ sâu.','images/exercises/legs.svg',NULL,3,'10-12',90,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(14,'Romanian Deadlift','romanian-deadlift','legs','intermediate','Barbell hoặc Dumbbell','Biến thể deadlift tập trung vào đùi sau và mông với chuyển động gập hông.','Đứng thẳng cầm thanh đòn trước đùi.\nHơi chùng gối, đẩy hông ra sau, hạ thanh đòn dọc theo chân.\nHạ đến khi đùi sau căng (khoảng giữa ống quyển).\nĐẩy hông về trước để đứng thẳng, siết mông.','Đùi sau, Mông, Lưng dưới','Lưng luôn thẳng, thanh đòn sát chân. Không hạ quá sâu nếu lưng bắt đầu cong.','images/exercises/legs.svg',NULL,3,'10',90,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(15,'Leg Extension','leg-extension','legs','beginner','Máy đá đùi','Bài cô lập đùi trước trên máy.','Ngồi vào máy, đệm chân đặt trên cổ chân.\nDuỗi thẳng chân, siết đùi trước ở đỉnh.\nHạ chậm về vị trí ban đầu.','Đùi trước','Không dùng mức tạ quá nặng gây áp lực lên khớp gối.','images/exercises/legs.svg',NULL,3,'12-15',60,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(16,'Bicep Curl','bicep-curl','arms','beginner','Dumbbell hoặc Barbell','Bài cuốn tạ cơ bản phát triển cơ tay trước.','Đứng thẳng, cầm tạ, lòng bàn tay hướng trước.\nGiữ khuỷu tay sát thân, cuốn tạ lên ngang vai.\nSiết tay trước ở đỉnh.\nHạ tạ chậm về vị trí ban đầu.','Tay trước','Không đánh võng lưng hay đẩy khuỷu tay ra trước.','images/exercises/arms.svg',NULL,3,'10-12',60,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(17,'Hammer Curl','hammer-curl','arms','beginner','Dumbbell','Biến thể cuốn tạ cầm búa, tác động tay trước và cẳng tay.','Đứng thẳng, cầm tạ đơn, lòng bàn tay hướng vào thân.\nCuốn tạ lên, giữ nguyên hướng cầm.\nHạ tạ chậm về vị trí ban đầu.','Tay trước, Cơ cánh tay, Cẳng tay','Có thể tập luân phiên hai tay để tập trung tốt hơn.','images/exercises/arms.svg',NULL,3,'10-12',60,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(18,'Tricep Pushdown','tricep-pushdown','arms','beginner','Máy cáp','Bài đẩy cáp xuống cô lập cơ tay sau.','Đứng trước máy cáp, nắm thanh hoặc dây thừng.\nKhép khuỷu tay sát thân.\nĐẩy thanh xuống đến khi duỗi thẳng tay.\nTrả thanh lên chậm, khuỷu tay giữ cố định.','Tay sau','Không dùng thân người đè xuống. Chỉ khuỷu tay chuyển động.','images/exercises/arms.svg',NULL,3,'12-15',45,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(19,'Plank','plank','core','beginner','Thảm tập','Bài giữ tĩnh tăng sức bền cơ core, hỗ trợ tư thế và các bài compound.','Chống cẳng tay xuống sàn, khuỷu tay dưới vai.\nDuỗi thẳng chân, thân người thẳng từ đầu đến gót.\nSiết bụng và mông, giữ tư thế theo thời gian quy định.','Cơ bụng, Core sâu, Lưng dưới','Không võng lưng hay nhô mông. Thở đều. Reps tính theo giây.','images/exercises/core.svg',NULL,3,'30-60',45,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(20,'Crunch','crunch','core','beginner','Thảm tập','Bài gập bụng cơ bản tập trung cơ bụng trên.','Nằm ngửa, co gối, bàn chân đặt trên sàn.\nĐặt tay sau đầu hoặc bắt chéo trước ngực.\nSiết bụng, nâng vai khỏi sàn.\nHạ người chậm về vị trí ban đầu.','Cơ bụng trên','Không kéo cổ bằng tay. Chuyển động nhỏ, tập trung siết bụng.','images/exercises/core.svg',NULL,3,'15-20',45,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(21,'Jumping Jack','jumping-jack','cardio','beginner','Không cần dụng cụ','Bài cardio khởi động toàn thân, tăng nhịp tim nhanh.','Đứng thẳng, hai chân khép, tay để hai bên.\nBật nhảy dang rộng hai chân, đồng thời vung tay qua đầu.\nBật nhảy trở về tư thế ban đầu.\nLặp lại liên tục với nhịp đều.','Toàn thân, Bắp chân, Vai','Tiếp đất nhẹ nhàng bằng mũi chân.','images/exercises/cardio.svg',NULL,3,'30',30,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(22,'Burpee','burpee','cardio','intermediate','Không cần dụng cụ','Bài cardio cường độ cao kết hợp squat, chống đẩy và bật nhảy.','Từ tư thế đứng, ngồi xổm và chống tay xuống sàn.\nBật hai chân ra sau về tư thế plank.\nThực hiện 1 lần chống đẩy (tùy chọn).\nThu chân về và bật nhảy lên cao, vỗ tay qua đầu.','Toàn thân, Đùi, Ngực, Core','Giữ nhịp phù hợp với thể lực, ưu tiên kỹ thuật hơn tốc độ.','images/exercises/cardio.svg',NULL,3,'10-15',60,'active','2026-10-05 03:47:38','2026-10-05 03:47:38'),(23,'Mountain Climber','mountain-climber','cardio','beginner','Không cần dụng cụ','Bài leo núi tại chỗ giúp đốt calo và tăng sức bền core.','Vào tư thế plank cao, tay thẳng dưới vai.\nKéo gối phải về phía ngực rồi đổi chân nhanh.\nLuân phiên hai chân liên tục.','Core, Vai, Đùi','Giữ hông thấp, không nhấp nhô mông.','images/exercises/cardio.svg',NULL,3,'30',30,'active','2026-10-05 03:47:38','2026-10-05 03:47:38');
