UNLOCK TABLES;
DROP TABLE IF EXISTS `workout_sets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `workout_sets` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `workout_session_id` bigint unsigned NOT NULL,
  `exercise_id` bigint unsigned NOT NULL,
  `set_number` int NOT NULL,
  `target_reps` int DEFAULT NULL,
  `actual_reps` int DEFAULT NULL,
  `target_weight` decimal(6,2) DEFAULT NULL,
  `actual_weight` decimal(6,2) DEFAULT NULL,
  `rpe` decimal(3,1) DEFAULT NULL,
  `rest_seconds` int NOT NULL DEFAULT '60',
  `completed` tinyint(1) NOT NULL DEFAULT '0',
  `note` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `workout_sets_workout_session_id_foreign` (`workout_session_id`),
  KEY `workout_sets_exercise_id_foreign` (`exercise_id`),
  CONSTRAINT `workout_sets_exercise_id_foreign` FOREIGN KEY (`exercise_id`) REFERENCES `exercises` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `workout_sets_workout_session_id_foreign` FOREIGN KEY (`workout_session_id`) REFERENCES `workout_sessions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=592 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

